import time
import functools
from typing import Callable, Any

# Decorador: logging
def log_calls(func: Callable) -> Callable:
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f'[LOG] {func.__name__} called with args={args}, kwargs={kwargs}')
        result = func(*args, **kwargs)
        print(f'[LOG] {func.__name__} returned {result}')
        return result
    return wrapper

# Decorador: retry con backoff exponencial
def retry(max_attempts: int = 3, base_delay: float = 1.0) -> Callable:
    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts - 1:
                        raise
                    delay = base_delay * (2 ** attempt)
                    print(f'[RETRY] {func.__name__} attempt {attempt+1} failed: {e}. Retrying in {delay}s')
                    time.sleep(delay)
        return wrapper
    return decorator

# Decorador: timing
def timed(func: Callable) -> Callable:
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f'[TIMING] {func.__name__} took {elapsed:.4f}s')
        return result
    return wrapper

# Decorador: cache
def cache(func: Callable) -> Callable:
    _cache = {}
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if key not in _cache:
            _cache[key] = func(*args, **kwargs)
        return _cache[key]
    return wrapper


class DataService:
    '''Sin repetición: decoradores aplicados selectivamente'''

    @log_calls
    @timed
    @retry(max_attempts=3, base_delay=1.0)
    def get_users(self):
        return self._fetch_users()

    @log_calls
    @timed
    @retry(max_attempts=5, base_delay=0.5)  # Retry diferente por método
    def get_orders(self):
        return self._fetch_orders()

    @cache
    def get_config(self, key):
        return self._fetch_config(key)

