from typing import Callable, Any, TypeVar, ParamSpec
from abc import ABC, abstractmethod

P = ParamSpec('P')
R = TypeVar('R')

# ========================================================================
#  DECORATOR PATTERN EN PYTHON
# ========================================================================
# Python tiene soporte nativo para decoradores con @syntax
# Un decorador es una función que toma una función y retorna una función
# que agrega comportamiento sin modificar la original.
#
# VENTAJAS SOBRE HERENCIA:
#   - Combinación dinámica: @log @retry @timed (en cualquier orden)
#   - No explosiona jerarquía: LoggingRetryTimedDataService es innecesario
#   - Selectivo: aplicas solo a los métodos que necesitan
#   - Reutilizable: mismo decorador para cualquier función

# ========================================================================
#  DECORADORES FUNCIONALES (LOS MÁS COMUNES EN PYTHON)
# ========================================================================

def log_calls(func: Callable[P, R]) -> Callable[P, R]:
    '''Loggea entrada y salida de la función'''
    @functools.wraps(func)
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        print(f'[LOG] {func.__name__}({args}, {kwargs})')
        result = func(*args, **kwargs)
        print(f'[LOG] {func.__name__} → {result}')
        return result
    return wrapper

def retry(max_attempts: int = 3, base_delay: float = 1.0, exceptions: tuple = (Exception,)) -> Callable:
    '''Retry con backoff exponencial'''
    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
                    if attempt < max_attempts - 1:
                        delay = base_delay * (2 ** attempt)
                        time.sleep(delay)
            raise last_exception
        return wrapper
    return decorator

def timed(func: Callable) -> Callable:
    '''Mide el tiempo de ejecución'''
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f'[TIMING] {func.__name__}: {elapsed:.4f}s')
        return result
    return wrapper

def validate_types(**type_hints):
    '''Valida tipos de argumentos en runtime'''
    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            import inspect
            sig = inspect.signature(func)
            bound = sig.bind(*args, **kwargs)
            bound.apply_defaults()
            for name, value in bound.arguments.items():
                if name in type_hints:
                    expected = type_hints[name]
                    if not isinstance(value, expected):
                        raise TypeError(f'{name} must be {expected.__name__}, got {type(value).__name__}')
            return func(*args, **kwargs)
        return wrapper
    return decorator

def singleton(cls):
    '''Convierte una clase en singleton'''
    instances = {}
    @functools.wraps(cls)
    def get_instance(*args, **kwargs):
        if cls not in instances:
            instances[cls] = cls(*args, **kwargs)
        return instances[cls]
    return get_instance

# ========================================================================
#  DECORADORES DE CLASE (WRAPPER PATTERN)
# ========================================================================
# Cuando necesitas decorar una clase entera o agregar estado

class Component(ABC):
    @abstractmethod
    def operation(self) -> str:
        pass

class ConcreteComponent(Component):
    def operation(self) -> str:
        return 'base'

class Decorator(Component):
    '''Decorator base: delega al componente envuelto'''
    def __init__(self, component: Component):
        self._component = component

    def operation(self) -> str:
        return self._component.operation()

class LoggingDecorator(Decorator):
    def operation(self) -> str:
        print(f'[LOG] Before operation')
        result = super().operation()
        print(f'[LOG] After operation: {result}')
        return result

class RetryDecorator(Decorator):
    def __init__(self, component: Component, max_attempts: int = 3):
        super().__init__(component)
        self.max_attempts = max_attempts

    def operation(self) -> str:
        for attempt in range(self.max_attempts):
            try:
                return super().operation()
            except Exception as e:
                if attempt == self.max_attempts - 1:
                    raise
        return ''

# Composición de decoradores:
component = ConcreteComponent()
logged = LoggingDecorator(component)
retried = RetryDecorator(logged, max_attempts=3)
print(retried.operation())
# [LOG] Before operation
# [LOG] After operation: base
# 'base'

