from abc import ABC, abstractmethod
from typing import Dict, Type

# Abstracción
class PaymentProcessor(ABC):
    @abstractmethod
    def charge(self, amount: float) -> dict:
        pass

    @abstractmethod
    def refund(self, transaction_id: str) -> dict:
        pass

# Implementaciones
class CreditCardProcessor(PaymentProcessor):
    def __init__(self, api_key, timeout=30, retry=3):
        self.api_key = api_key
        self.timeout = timeout
        self.retry = retry

    def charge(self, amount):
        return {'method': 'credit_card', 'amount': amount, 'status': 'ok'}

    def refund(self, transaction_id):
        return {'method': 'credit_card', 'refund_id': transaction_id}

class PayPalProcessor(PaymentProcessor):
    def __init__(self, client_id, secret, sandbox=False):
        self.client_id = client_id
        self.secret = secret
        self.sandbox = sandbox

    def charge(self, amount):
        return {'method': 'paypal', 'amount': amount, 'status': 'ok'}

    def refund(self, transaction_id):
        return {'method': 'paypal', 'refund_id': transaction_id}

# Factory: centraliza la creación
class PaymentProcessorFactory:
    _registry: Dict[str, Type[PaymentProcessor]] = {}
    _config: dict = {}

    @classmethod
    def register(cls, name: str, processor_class: Type[PaymentProcessor]):
        cls._registry[name] = processor_class

    @classmethod
    def configure(cls, config: dict):
        cls._config = config

    @classmethod
    def create(cls, method: str) -> PaymentProcessor:
        if method not in cls._registry:
            raise ValueError(f'Unknown payment method: {method}')

        processor_class = cls._registry[method]
        method_config = cls._config.get(method, {})
        return processor_class(**method_config)

# Registrar processors
PaymentProcessorFactory.register('credit_card', CreditCardProcessor)
PaymentProcessorFactory.register('paypal', PayPalProcessor)

# Configurar
