class PluginFactory:
    '''Descubre plugins automáticamente desde un directorio'''

    def __init__(self, plugin_dir: str, base_class: type):
        self._plugins = {}
        self._base_class = base_class
        self._discover(plugin_dir)

    def _discover(self, plugin_dir: str):
        for file in Path(plugin_dir).glob('*.py'):
            if file.name.startswith('_'):
                continue
            module = importlib.import_module(f'plugins.{file.stem}')
            for name in dir(module):
                obj = getattr(module, name)
                if (isinstance(obj, type) and 
                    issubclass(obj, self._base_class) and 
                    obj is not self._base_class):
                    self._plugins[name.lower()] = obj

    def create(self, name: str, **kwargs):
        if name not in self._plugins:
            raise ValueError(f'Unknown plugin: {name}')
        return self._plugins[name](**kwargs)

