    def find_by_id(self, task_id: int) -> Optional[Task]: ...

class SQLiteTaskRepository(TaskRepository):
    def __init__(self, db_path: str):
        self._conn = sqlite3.connect(db_path)
        self._conn.execute(
            'CREATE TABLE IF NOT EXISTS tasks '
            '(id INTEGER PRIMARY KEY, title TEXT, description TEXT, priority INTEGER)'
        )

    def save(self, task: Task) -> int:
        cursor = self._conn.execute(
            'INSERT INTO tasks (title, description, priority) VALUES (?, ?, ?)',
            (task.title, task.description, int(task.priority))
        )
        self._conn.commit()
        return cursor.lastrowid

    def find_all(self) -> List[Task]:
        rows = self._conn.execute('SELECT * FROM tasks').fetchall()
        return [Task(id=r[0], title=r[1], description=r[2], priority=Priority(r[3])) for r in rows]

    def find_by_id(self, task_id: int) -> Optional[Task]:
        row = self._conn.execute('SELECT * FROM tasks WHERE id = ?', (task_id,)).fetchone()
        if row:
            return Task(id=row[0], title=row[1], description=row[2], priority=Priority(row[3]))
        return None

