    @abstractmethod
    def notify(self, message: str) -> bool: ...

class HttpNotifier(Notifier):
    def __init__(self, api_url: str, api_key: str):
        self._url = api_url
        self._key = api_key

    def notify(self, message: str) -> bool:
        import requests
        response = requests.post(
            self._url,
            json={'message': message, 'key': self._key},
            timeout=10,
            verify=True
        )
        return response.status_code == 200

