from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import List, Optional, Dict, Any
from datetime import datetime
from pathlib import Path
import sqlite3
import json
import csv
import io
import os

# ========================================================================
#  CAPA DE DOMINIO
# ========================================================================

@dataclass
class Report:
    id: Optional[int]
    name: str
    data: str
    created_at: str = field(default_factory=lambda: datetime.now().isoformat())
    row_count: int = 0

class ReportFormat(ABC):
    @abstractmethod
    def format(self, rows: List[dict]) -> str: ...

    @property
    @abstractmethod
    def extension(self) -> str: ...

class JsonFormat(ReportFormat):
    def format(self, rows):
        return json.dumps(rows, indent=2, default=str)
    @property
    def extension(self): return '.json'

class CsvFormat(ReportFormat):
    def format(self, rows):
        if not rows: return ''
        output = io.StringIO()
        writer = csv.DictWriter(output, fieldnames=rows[0].keys())
        writer.writeheader()
        writer.writerows(rows)
        return output.getvalue()
    @property
    def extension(self): return '.csv'

class HtmlFormat(ReportFormat):
    def format(self, rows):
        if not rows: return '<table></table>'
        headers = ''.join(f'<th>{k}</th>' for k in rows[0].keys())
        body = ''.join('<tr>' + ''.join(f'<td>{v}</td>' for v in row.values()) + '</tr>' for row in rows)
        return f'<table><thead><tr>{headers}</tr></thead><tbody>{body}</tbody></table>'
    @property
    def extension(self): return '.html'

# ========================================================================
#  CAPA DE DATOS
# ========================================================================

class ReportRepository(ABC):
    @abstractmethod
    def save(self, report: Report) -> int: ...
    @abstractmethod
    def find_all(self) -> List[Report]: ...
    @abstractmethod
    def find_by_id(self, report_id: int) -> Optional[Report]: ...
    @abstractmethod
    def delete(self, report_id: int) -> bool: ...
    @abstractmethod
    def execute_query(self, query: str, params: tuple = ()) -> List[dict]: ...

class SQLiteReportRepository(ReportRepository):
    def __init__(self, db_path: str):
        self._conn = sqlite3.connect(db_path)
        self._conn.row_factory = sqlite3.Row
        self._conn.execute(
            'CREATE TABLE IF NOT EXISTS reports '
            '(id INTEGER PRIMARY KEY, name TEXT, data TEXT, created TEXT, row_count INTEGER)'
        )

    def save(self, report: Report) -> int:
        cursor = self._conn.execute(
            'INSERT INTO reports (name, data, created, row_count) VALUES (?, ?, ?, ?)',
            (report.name, report.data, report.created_at, report.row_count)
        )
        self._conn.commit()
        return cursor.lastrowid

    def find_all(self) -> List[Report]:
        rows = self._conn.execute('SELECT * FROM reports').fetchall()
        return [Report(id=r['id'], name=r['name'], data=r['data'],
                       created_at=r['created'], row_count=r['row_count']) for r in rows]

    def find_by_id(self, report_id: int) -> Optional[Report]:
        row = self._conn.execute('SELECT * FROM reports WHERE id = ?', (report_id,)).fetchone()
        if row:
            return Report(id=row['id'], name=row['name'], data=row['data'],
                          created_at=row['created'], row_count=row['row_count'])
        return None

    def delete(self, report_id: int) -> bool:
        cursor = self._conn.execute('DELETE FROM reports WHERE id = ?', (report_id,))
        self._conn.commit()
        return cursor.rowcount > 0

    def execute_query(self, query: str, params: tuple = ()) -> List[dict]:
        rows = self._conn.execute(query, params).fetchall()
        return [dict(r) for r in rows]

# ========================================================================
#  CAPA DE NOTIFICACIÓN
# ========================================================================

class Notifier(ABC):
    @abstractmethod
    def notify(self, message: str) -> bool: ...

class HttpNotifier(Notifier):
    def __init__(self, api_url: str, api_key: str):
        self._url = api_url
        self._key = api_key

    def notify(self, message: str) -> bool:
        try:
            import requests
            response = requests.post(
                self._url,
                json={'message': message, 'key': self._key},
                timeout=10, verify=True
            )
            return response.status_code == 200
        except Exception:
            return False

class NullNotifier(Notifier):
    def notify(self, message: str) -> bool:
        return True  # No-op para desarrollo/tests

# ========================================================================
#  CAPA DE SERVICIO
# ========================================================================

class ReportFormatFactory:
    _formats = {'json': JsonFormat, 'csv': CsvFormat, 'html': HtmlFormat}

    @classmethod
    def register(cls, name: str, format_class: type):
        cls._formats[name] = format_class

    @classmethod
    def create(cls, name: str) -> ReportFormat:
        if name not in cls._formats:
            raise ValueError(f'Unknown format: {name}. Available: {list(cls._formats.keys())}')
        return cls._formats[name]()

class ReportService:
    def __init__(self, repo: ReportRepository, notifier: Optional[Notifier] = None):
        self._repo = repo
        self._notifier = notifier or NullNotifier()

    def generate(self, name: str, query: str, params: tuple = (),
                 format_name: str = 'json') -> Report:
        if not name or len(name) < 3:
            raise ValueError('Report name must be at least 3 characters')

        rows = self._repo.execute_query(query, params)
        formatter = ReportFormatFactory.create(format_name)
        data = formatter.format(rows)

        report = Report(id=None, name=name, data=data, row_count=len(rows))
        report.id = self._repo.save(report)

        self._notifier.notify(f'Report "{name}" generated ({len(rows)} rows)')
        return report

    def list_reports(self) -> List[Report]:
        return self._repo.find_all()

    def delete_report(self, report_id: int) -> bool:
        return self._repo.delete(report_id)

    def export_all(self, directory: str, format_name: str = 'json') -> int:
        Path(directory).mkdir(parents=True, exist_ok=True)
        reports = self._repo.find_all()
        formatter = ReportFormatFactory.create(format_name)

        for report in reports:
            path = Path(directory) / f'report_{report.id}{formatter.extension}'
            path.write_text(report.data, encoding='utf-8')

        return len(reports)

# ========================================================================
#  CAPA DE PRESENTACIÓN
# ========================================================================

class ReportCLI:
    def __init__(self, service: ReportService):
        self._service = service

    def display_reports(self):
        reports = self._service.list_reports()
        print('\n=== REPORTS ===')
        for r in reports:
            print(f'  [{r.id}] {r.name} ({r.row_count} rows, {r.created_at})')

    def generate_interactive(self):
        name = input('Report name: ')
        query = input('SQL query: ')
        format_name = input('Format (json/csv/html): ') or 'json'

        try:
            report = self._service.generate(name, query, format_name=format_name)
            print(f'✓ Report "{report.name}" generated (id={report.id}, {report.row_count} rows)')
        except ValueError as e:
            print(f'✗ Error: {e}')

# ========================================================================
#  COMPOSITION ROOT
# ========================================================================

def create_application(config: dict) -> ReportCLI:
    repo = SQLiteReportRepository(config['db_path'])

    notifier = NullNotifier()
    if config.get('notifications_enabled'):
        notifier = HttpNotifier(
            api_url=config['notification_url'],
            api_key=config['notification_api_key']
        )

    service = ReportService(repo=repo, notifier=notifier)
    return ReportCLI(service=service)

